export const CATEGORIES=['problem','method','result','limitation'];
export const SECTION_LABELS={problem:'研究問題',method:'方法',result:'成果',limitation:'限制',themes:'研究主軸',evolution:'研究演進',methods:'共同方法',fit:'申請方向關聯',questions:'可追問的研究問題'};
export function safeUrl(s){try{let u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
export function normalize(s){return String(s).normalize('NFKC').replace(/\s+/g,' ').trim()}
export function safeName(s){return String(s).replace(/[^\p{L}\p{N}_-]/gu,'-').slice(0,50)||'professor'}
export function component(s){if(typeof s!=='string'||!s||/[\\/]/.test(s)||s==='.'||s==='..')throw Error('不安全的檔案路徑');return s}
export async function digest(value){let b=typeof value==='string'?new TextEncoder().encode(value):value;return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',b)),x=>x.toString(16).padStart(2,'0')).join('')}
export function chunks(pages,limit=16000){let out=[],cur=[],size=0;for(let p of pages){if(!p.text.trim())continue;for(let start=0;start<p.text.length;start+=limit-300){let text=p.text.slice(start,start+limit-300);if(size+text.length>limit&&cur.length){out.push(cur);cur=[];size=0}cur.push({page:p.page,text});size+=text.length}}if(cur.length)out.push(cur);return out}
export function validateClaims(raw,papers,sections){if(!raw||!Array.isArray(raw.claims))throw Error('模型未回傳 claims 陣列');let accepted=[],rejected=[];for(let [i,c]of raw.claims.entries()){let why='';if(!c||!sections.includes(c.section)||!['evidence','inference'].includes(c.kind)||typeof c.text!=='string'||!c.text.trim()||c.text.length>2500)why='主張格式不符';else if(!Array.isArray(c.citations)||!c.citations.length||c.citations.length>8)why='缺少引用';else for(let r of c.citations){let doc=papers.find(p=>p.id===r.paperId),page=doc?.pages.find(p=>p.page===r.page);if(!page||typeof r.quote!=='string'||normalize(r.quote).length<12||normalize(r.quote).length>800||!normalize(page.text).includes(normalize(r.quote))){why='頁碼或原文片段無法核對';break}}if(why){rejected.push({index:i+1,reason:why});continue}accepted.push({section:c.section,kind:c.kind,text:c.text.trim(),citations:c.citations.map(r=>({paperId:r.paperId,page:r.page,quote:r.quote}))})}return {claims:accepted,rejected}}
export function fingerprint(p,interests){return JSON.stringify({interests,professor:[p.name,p.school,p.program,p.url],papers:p.papers.map(q=>({id:q.id,title:q.title,year:q.year,source:q.url,hash:q.hash,analysisAt:q.analysisAt,status:q.status}))})}
export function reportMarkdown(title,result,papers){let labels=SECTION_LABELS;return `# ${title}\n\n模型：${result.model}\n產生時間：${result.createdAt}\n資料範圍：${result.coverage||'依所附頁碼'}\n\n注意：引用片段已比對擷取文字；不代表模型推論或語意已由人工驗證。PDF 頁碼自檔案第 1 頁起算。\n\n`+Object.entries(labels).map(([k,label])=>{let list=result.claims.filter(c=>c.section===k);return list.length?`## ${label}\n\n`+list.map(c=>`- **${c.kind==='evidence'?'依原文整理':'推論／建議'}**：${c.text}\n`+c.citations.map(r=>`  - [${r.paperId}, PDF p.${r.page}] ${papers.find(p=>p.id===r.paperId)?.title||''}\n    > ${r.quote.replace(/\n/g,' ')}`).join('\n')).join('\n\n'):''}).filter(Boolean).join('\n\n')+`\n\n## 範圍與缺口\n${result.gaps||'未另外提供'}\n被排除的無法核對主張：${result.rejected?.length||0}\n`}
